/**
 * Generates a summary using Anthropic Claude API.
 * @param params - The parameters for the Claude summary.
 * @returns The generated summary.
 */
export async function getClaudeSummary(params: ClaudeSummaryParams): Promise<string> {
  const { apiKey, model, prompt, text, logger, baseURL, defaultHeaders, timeout } = params;
  try {
    const usedModel = model || 'claude-4-6-opus';
    logger.debug(`[CLAUDE-DEBUG] Using Anthropic API with model: ${usedModel}`);
    const anthropic = new Anthropic({
      apiKey,
      ...(baseURL ? { baseURL } : {}),
      ...(defaultHeaders ? { defaultHeaders } : {}),
      ...(timeout ? { timeout } : {}),
    });
    const response = await anthropic.messages.create({
      model: usedModel,
      max_tokens: 1024,
      system: prompt,
      messages: [{ role: 'user', content: text }],
    });
    // @ts-expect-error - SDK type definitions might be inconsistent with the version
    const result = response.content[0]?.text?.trim() || '';
    logger.debug(`[CLAUDE-DEBUG] Result: ${result.substring(0, 100)}...`);
    return result;
  } catch (e) {
    const msg = toErrorMessage(e);
    if (isPermanentFailure(msg)) throw new PermanentProviderError(msg, 'claude');
    logger.error(`[CLAUDE-ERROR] ${msg}`);
    return '';
  }
}

/**
 * Generates a summary using a CLI tool.
 * @param params - The parameters for the CLI summary.
 * @returns The generated summary.
 */
export async function getCLISummary(params: CLISummaryParams): Promise<string> {
  const { command, prompt, text, logger, timeout } = params;
  try {
    logger.debug(`[CLI-DEBUG] Using CLI command: ${command}`);
    const result = execSync(command, {
      input: `${prompt}\n\n${text}`,
      encoding: 'utf-8',
      ...(timeout ? { timeout } : {}),
    });
    return result.trim();
  } catch (e) {
    logger.error(`[CLI-ERROR] ${toErrorMessage(e)}`);
    return '';
  }
}

/**
 * Generates a summary using OpenAI or any OpenAI-compatible API.
 * @param params - The parameters for the OpenAI/compatible summary.
 * @returns The generated summary.
 */
export async function getOpenAISummary(params: OpenAISummaryParams): Promise<string> {
  const {
    apiKey,
    model,
    prompt,
    text,
    logger,
    baseURL,
    defaultHeaders,
    timeout,
    providerName = 'openai',
  } = params;
  const preset = OPENAI_COMPATIBLE_PROVIDERS[providerName];
  const usedModel = model || preset?.defaultModel || 'gpt-5.3';
  const resolvedBaseURL =
    baseURL || (providerName !== 'openai' && preset ? preset.baseURL : undefined);
  const tag = providerName.toUpperCase();

  try {
    logger.debug(`[${tag}-DEBUG] Using ${providerName} API with model: ${usedModel}`);
    const client = new OpenAI({
      apiKey: apiKey || 'not-needed',
      ...(resolvedBaseURL ? { baseURL: resolvedBaseURL } : {}),
      ...(defaultHeaders ? { defaultHeaders } : {}),
      ...(timeout ? { timeout } : {}),
    });
    const completion = await client.chat.completions.create({
      model: usedModel,
      messages: [
        { role: 'system', content: prompt },
        { role: 'user', content: text },
      ],
      temperature: 0.5,
    });
    const result = completion.choices[0]?.message?.content?.trim() || '';
    logger.debug(`[${tag}-DEBUG] Result: ${result.substring(0, 100)}...`);
    return result;
  } catch (e) {
    const msg = toErrorMessage(e);
    if (isPermanentFailure(msg)) throw new PermanentProviderError(msg, providerName);
    logger.error(`[${tag}-ERROR] ${msg}`);
    return '';
  }
}

/**
 * Generates a summary using Google Gemini API.
 * @param params - The parameters for the Gemini summary.
 * @returns The generated summary.
 */
export async function getGeminiSummary(params: GeminiSummaryParams): Promise<string> {
  const { apiKey, model, prompt, text, logger, thinkingLevel, thinkingBudget } = params;
  try {
    const usedModel = model || 'gemini-2.5-flash';
    logger.debug(`[GENAI-DEBUG] Using Google Gemini API with model: ${usedModel}`);
    const ai = new GoogleGenAI({ apiKey });

    const config: {
      thinkingConfig?: {
        includeThoughts: boolean;
        thinkingLevel?: ThinkingLevel;
        thinkingBudget?: number;
      };
    } = {};
    if (thinkingLevel || thinkingBudget) {
      config.thinkingConfig = { includeThoughts: false };
      if (thinkingLevel) config.thinkingConfig.thinkingLevel = thinkingLevel as ThinkingLevel;
      if (thinkingBudget) config.thinkingConfig.thinkingBudget = thinkingBudget;
    }

    logger.debug(`[GENAI-DEBUG] Calling generateContent with model: ${usedModel}`);
    const result = await ai.models.generateContent({
      model: usedModel,
      contents: `${prompt}\n\n${text}`,
      config,
    });
    const resUnknown = result as unknown as { text: string | (() => string) };
    const response =
      (typeof resUnknown.text === 'function' ? resUnknown.text() : resUnknown.text) || '';
    logger.debug(`[GENAI-DEBUG] Result: ${response.substring(0, 100)}...`);
    return response;
  } catch (e) {
    const msg = toErrorMessage(e);
    if (isPermanentFailure(msg)) throw new PermanentProviderError(msg, 'gemini');
    logger.error(`[GENAI-ERROR] ${msg}`);
    return '';
  }
}

/**
 * Generates a summary using Ollama API.
 * @param params - The parameters for the Ollama summary.
 * @returns Summary string.
 */
export async function getOllamaSummary(params: OllamaSummaryParams): Promise<string> {
  const { model, prompt, text, logger, host, maxRetries = 5, retryDelayMs = 10 } = params;
  const effectiveHost = host || process.env.OLLAMA_HOST;
  const client = host && typeof Ollama === 'function' ? new Ollama({ host }) : ollama;
  const usedModel = model || 'llama3';

  async function attemptRequest(attempt: number): Promise<string> {
    try {
      logger.debug(`[OLLAMA-DEBUG] Attempt ${attempt}/${maxRetries}`);
      logger.debug(`[OLLAMA-DEBUG] Model: ${usedModel}`);
      logger.debug(`[OLLAMA-DEBUG] Prompt: ${prompt}`);
      logger.debug(
        `[OLLAMA-DEBUG] Input (first part): ${text.substring(0, 500)}... (Length: ${text.length})`
      );
      if (effectiveHost) {
        logger.debug(`[OLLAMA-DEBUG] OLLAMA_HOST: ${effectiveHost}`);
      }
      const requestObj = {
        model: usedModel,
        messages: [{ role: 'user', content: `${prompt}\n${text}` }],
      };
      logger.debug(`[OLLAMA-DEBUG] Request object: ${JSON.stringify(requestObj)}`);
      const response = await client.chat(requestObj);
      logger.debug(`[OLLAMA-DEBUG] RAW response: ${JSON.stringify(response)}`);
      if (!response.message?.content?.trim()) {
        logger.debug(`[OLLAMA-DEBUG] Response is empty (attempt ${attempt})!`);
        if (attempt < maxRetries) {
          logger.debug(`[OLLAMA-DEBUG] Waiting ${retryDelayMs / 1000}s before retry...`);
          await new Promise<void>((resolve) => {
            setTimeout(resolve, retryDelayMs);
          });
          return await attemptRequest(attempt + 1);
        }
        logger.error(`[OLLAMA-DEBUG] No valid response after ${maxRetries} attempts.`);
        return '';
      }
      return response.message.content.trim();
    } catch (e) {
      const errDetail = toErrorMessage(e);
      logger.debug(`[OLLAMA-DEBUG] Request failed (attempt ${attempt}): ${errDetail}`);
      if (attempt < maxRetries) {
        logger.debug(`[OLLAMA-DEBUG] Waiting ${retryDelayMs / 1000}s before retry...`);
        await new Promise<void>((resolve) => {
          setTimeout(resolve, retryDelayMs);
        });
        return attemptRequest(attempt + 1);
      }
      logger.error(
        `[OLLAMA-DEBUG] No valid response after ${maxRetries} attempts. Last error: ${errDetail}`
      );
      return '';
    }
  }
  return attemptRequest(1);
}

/**
 * Generates a summary using a custom user-supplied handler function.
 * @param params - The parameters for the custom summary.
 * @returns The generated summary.
 */
export async function getCustomSummary(params: CustomSummaryParams): Promise<string> {
  const { handler, apiKey, model, prompt, text, aiUrl, logger } = params;
  try {
    logger.debug('[CUSTOM-DEBUG] Executing custom aiHandler');
    const result = await handler({ prompt, text, model, apiKey, aiUrl });
    return (result || '').trim();
  } catch (e) {
    const msg = toErrorMessage(e);
    if (isPermanentFailure(msg)) throw new PermanentProviderError(msg, 'custom');
    logger.error(`[CUSTOM-ERROR] ${msg}`);
    return '';
  }
}

function requiresApiKey(provider: string, options: AISummaryOptions): boolean {
  if (options.aiHandler || options.aiUrl) return false;
  return !['ollama', 'cli', 'custom', 'openai-compatible'].includes(provider);
}

/**
 * Generates an AI summary for the given text using the selected provider and caching.
 * @param options - Options for summary generation.
 * @returns AI summary as string (Promise).
 */
export async function generateAISummary(options: AISummaryOptions): Promise<string> {
  const { logger, provider, apiKey, model, prompt, text, cacheDir, debug } = options;

  function debugLog(...args: unknown[]) {
    /* v8 ignore next -- !logger branch: logger is always supplied by callers */
    if ((!logger || typeof logger.debug !== 'function') && debug) {
      console.debug('[LLMS-TXT-DEBUG]', ...args);
      return;
    }
    /* v8 ignore next -- false branch: only reached when logger has no debug AND debug=false (silent mode) */
    if (logger && typeof logger.debug === 'function') {
      logger.debug(...args);
    }
  }

  const wrappedLogger: AstroLogger = {
    /* v8 ignore next -- info() is a pass-through; no provider calls logger.info */
    info: (...args: unknown[]) => logger.info(...args),
    warn: (...args: unknown[]) => logger.warn(...args),
    error: (...args: unknown[]) => logger.error(...args),
    debug: debugLog,
  };

  const effectiveProvider = provider || (options.aiHandler ? 'custom' : '');

  if (!effectiveProvider || (requiresApiKey(effectiveProvider, options) && !apiKey)) {
    wrappedLogger.warn(
      '[DEBUG] No AI provider specified or API key missing! No AI summary will be generated.'
    );
    return '';
  }

  if (permanentlyFailedProviders.has(effectiveProvider)) {
    return '';
  }
  const hash = crypto
    .createHash('sha256')
    .update([effectiveProvider, model, options.aiUrl || '', prompt, text].join('||'))
    .digest('hex');
  const cachePath = cacheDir ? path.join(cacheDir, `${hash}.json`) : '';

  function readCache(): string | null {
    if (cacheDir && fs.existsSync(cachePath)) {
      try {
        const cached = JSON.parse(fs.readFileSync(cachePath, 'utf-8'));
        if (cached && typeof cached.summary === 'string') {
          wrappedLogger.debug(`AI cache hit for hash ${hash}`);
          return cached.summary;
        }
      } catch (e) {
        wrappedLogger.warn(`Error reading AI cache: ${toErrorMessage(e)}`);
      }
    }
    return null;
  }

  async function getProviderSummary(): Promise<string> {
    if (options.aiHandler) {
      return getCustomSummary({
        handler: options.aiHandler,
        apiKey,
        model,
        prompt,
        text,
        aiUrl: options.aiUrl,
        logger: wrappedLogger,
      });
    }

    if (effectiveProvider in OPENAI_COMPATIBLE_PROVIDERS) {
      return getOpenAISummary({
        apiKey,
        model,
        prompt,
        text,
        logger: wrappedLogger,
        baseURL: options.aiUrl,
        defaultHeaders: options.aiHeaders,
        timeout: options.aiTimeoutMs,
        providerName: effectiveProvider,
      });
    }

    switch (effectiveProvider) {
      case 'gemini':
        return getGeminiSummary({
          apiKey,
          model,
          prompt,
          text,
          logger: wrappedLogger,
          thinkingLevel: options.geminiThinkingLevel,
          thinkingBudget: options.geminiThinkingBudget,
        });
      case 'claude':
      case 'anthropic':
        return getClaudeSummary({
          apiKey,
          model,
          prompt,
          text,
          logger: wrappedLogger,
          baseURL: options.aiUrl,
          defaultHeaders: options.aiHeaders,
          timeout: options.aiTimeoutMs,
        });
      case 'ollama':
        return getOllamaSummary({
          model,
          prompt,
          text,
          logger: wrappedLogger,
          host: options.aiUrl,
          maxRetries: options.aiRetries,
          retryDelayMs: options.aiRetryDelayMs,
        });
      case 'cli':
        return getCLISummary({
          command: options.cliCommand || 'cat',
          prompt,
          text,
          logger: wrappedLogger,
          timeout: options.aiTimeoutMs,
        });
      default:
        wrappedLogger.warn('Unknown provider.');
        return '';
    }
  }

  const cachedSummary = readCache();
  if (cachedSummary) {
    return cachedSummary;
  }
  let summary = '';
  try {
    summary = await getProviderSummary();
  } catch (e) {
    /* v8 ignore next -- only PermanentProviderError is thrown by provider wrappers */
    if (e instanceof PermanentProviderError) {
      permanentlyFailedProviders.add(effectiveProvider);
      wrappedLogger.error(`[${effectiveProvider.toUpperCase()}-ERROR] ${e.message}`);
      wrappedLogger.warn(
        `[llms-txt] AI provider '${effectiveProvider}' failed permanently (e.g. invalid API key). Skipping remaining pages.`
      );
      return '';
    }
  }
  if (cacheDir && summary) {
    try {
      fs.writeFileSync(cachePath, JSON.stringify({ summary }), 'utf-8');
      wrappedLogger.debug(`AI response cached at ${cachePath}`);
    } catch (e) {
      wrappedLogger.warn(`Error writing AI cache: ${toErrorMessage(e)}`);
    }
  }
  return summary;
}
